const RR_CITY_FR=new Map([["Peiting", "Pétine"], ["Mapleriver", "Érableuve"], ["Windale", "Vindelle"], ["Victoria", "Victoria"], ["Prinsburg", "Princebourg"], ["Yenchia", "Yenchia"], ["Touraine", "Touraine"], ["Somerfield", "Somerfield"], ["Havenbolme", "Havenbolme"], ["Bayarfort", "Bayarfort"], ["Amptonside", "Amptonside"], ["Yuchow", "Yuchou"], ["Cranford", "Cranford"], ["Southend", "Southend"], ["Hiltsbury", "Hiltsbury"], ["Binchester", "Bincastre"], ["Barton", "Barton"], ["Norbourne", "Norbourne"], ["Medway", "Medway"], ["Rotherham", "Rotherham"], ["Whitehurst", "Blanchebois"], ["Grafton", "Grafton"], ["Wardour", "Wardour"], ["Ribeauvillé", "Ribeauvillé"], ["Farinport", "Farinport"], ["Kingsbury", "Bourg-le-Roi"], ["Marlbury", "Marlbury"], ["Pinehurst", "Pinehurst"], ["Hanjin", "Hanjin"], ["Chatham", "Chatham"], ["Sulgen", "Sulgen"], ["Belwich", "Belwich"], ["Königstadt", "Villeroi"], ["Yungang", "Yungang"], ["Brunswick", "Brunswick"], ["Linhai New Town", "Linhai-Ville-Nouvelle"], ["Hengchu", "Hengchu"]]);
function rrCityFr(v){const c=v.slice(0,-' (any station)'.length);return (RR_CITY_FR.get(c)||c)+' (toutes gares)'}
function rrPlaceLabel(v){let fr=false;try{fr=rrActiveLocale==='fr'}catch(_){}return fr&&RR_CITIES.has(v)?rrCityFr(v):v}
const RR_CITY_LABELS=[...RR_CITIES.keys()].sort((a,b)=>a.localeCompare(b));
function rrSelectValue(el,name){if(name&&![...el.options].some(o=>o.value===name))el.append(new Option(name,name));el.value=name||''}
function stationList(){RR_STATION_NAMES=[...S.keys()].sort((a,b)=>a.localeCompare(b));for(const id of ['stationSelect','from','to'])$(id).replaceChildren(new Option(id==='stationSelect'?'Choose station':'Choose station',''));rrSelectValue(stationSelect,currentStation);for(const id of ['from','to'])$(id).value=''}   // journeys start empty
function statusTone(s){const v=String(s).toLowerCase();return v.startsWith('cancel')?'cancelled':v.startsWith('expected')||v.includes('delay')?'expected':v.startsWith('on time')?'on-time':'neutral'}
function statusTag(s){return `<span class="status-tag status-${statusTone(s)}">${s}</span>`}

// Three searchable selectors with listbox navigation; original selects remain the source of truth.
const pickerViews=new Map();
function setupSearchPicker(id){
 const select=$(id);
 const shell=document.createElement('div');shell.className='search-picker'+(id==='stationSelect'?' search-picker-main':'');
 const trigger=document.createElement('div');trigger.className='picker-control';
 const input=document.createElement('input');input.type='text';input.className='picker-input';
 input.id=id+'Input';input.autocomplete='off';input.spellcheck=false;
 input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');
 input.setAttribute('aria-haspopup','listbox');input.setAttribute('aria-expanded','false');
 input.setAttribute('aria-controls',id+'List');
 input.setAttribute('aria-label',id==='stationSelect'?'Current station':id==='from'?'From station':'To station');
 input.placeholder='Search station';
 const list=document.createElement('div');list.className='picker-list';list.id=id+'List';list.setAttribute('role','listbox');
 if(id==='stationSelect')trigger.insertAdjacentHTML('beforeend','<svg class="picker-search-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-ui-find"></use></svg>');   // search icon at the left of the station box
 trigger.append(input);shell.append(trigger,list);select.parentElement.insertBefore(shell,select);select.classList.add('native-select');
 const names=RR_STATION_NAMES,normalize=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().trim();const norm=names.map(n=>normalize(n));
 let open=false,items=[],active=0;
 function sync(){input.value=rrPlaceLabel(select.value);input.title=input.value;}
 function shut(){open=false;list.classList.remove('open');shell.classList.remove('open');input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');sync();}
 function closeOthers(){for(const [key,v] of pickerViews)if(key!==id)v.shut();}
 function choose(name){rrSelectValue(select,name);shut();select.dispatchEvent(new Event('change',{bubbles:true}));input.focus({preventScroll:true});}
 function mark(){const opts=[...list.querySelectorAll('.picker-option')];opts.forEach((opt,i)=>{opt.classList.toggle('active',i===active);opt.setAttribute('aria-selected',String(items[i]===select.value))});if(opts[active]){input.setAttribute('aria-activedescendant',opts[active].id);opts[active].scrollIntoView({block:'nearest'});}}
 function render(q=''){
  // Phones: never build thousands of option buttons. Empty box = the major stations; typing = the best 50 matches.
  const term=normalize(q);
  if(!term)items=[...LABELS].sort((a,b)=>a.localeCompare(b));
  else{const hit=[];for(let i=0;i<names.length;i++){const k=norm[i].indexOf(term);if(k>=0)hit.push([k===0?0:1,names[i]])}
   hit.sort((a,b)=>a[0]-b[0]||a[1].localeCompare(b[1]));items=hit.slice(0,50).map(h=>h[1]);
   if(id!=='stationSelect')items.unshift(...RR_CITY_LABELS.filter(c=>normalize(c).startsWith(term)||normalize(rrCityFr(c)).startsWith(term)))}
  if(select.value&&!items.includes(select.value)&&!term)items.unshift(select.value);
  active=Math.max(0,items.indexOf(select.value));list.replaceChildren();
  if(!items.length){const empty=document.createElement('div');empty.className='picker-empty';empty.textContent='No matching stations';list.append(empty);return;}
  items.forEach((name,i)=>{const o=document.createElement('button');o.type='button';o.className='picker-option';o.id=id+'Opt'+i;o.setAttribute('role','option');o.textContent=name;if(RR_CITIES.has(name))o.classList.add('picker-city');o.addEventListener('pointerdown',e=>e.preventDefault());o.addEventListener('click',()=>choose(name));list.append(o)});mark();
 }
 function show(query=''){closeOthers();render(query);open=true;shell.classList.add('open');list.classList.add('open');input.setAttribute('aria-expanded','true');}
 // No drop-down until the user types: the list opens with the first letter and closes again when the box is emptied.
 function hide(){open=false;list.classList.remove('open');shell.classList.remove('open');input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
 input.addEventListener('focus',()=>input.select());
 input.addEventListener('input',()=>{if(input.value.trim()){show(input.value);active=0;mark()}else hide()});
 input.addEventListener('keydown',e=>{
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(open&&items.length){active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;mark()}}
  else if(e.key==='Enter'){e.preventDefault();if(!open)return;if(items.length)choose(items[active]);else shut();}
  else if(e.key==='Escape'){e.preventDefault();shut();input.blur()}
  else if(e.key==='Tab')shut();
 });
 select.addEventListener('change',sync);
 pickerViews.set(id,{shell,shut,sync});sync();
}
document.addEventListener('pointerdown',e=>{for(const {shell,shut} of pickerViews.values())if(!shell.contains(e.target))shut()});
function timeOrdinal(s){const m=String(s).match(/^(\d{1,2}):(\d{2})(?:\s*\+(\d+))?/);return m?(+m[1])*60+(+m[2])+(+(m[3]||0))*1440:0}
// Boards run as a rolling 24-hour window from the current time. Trains that
// have already gone today reappear at the end as tomorrow's services.
function rrWithBoardTime(t){
 const rel=rrRelative(stopOrdinal(t,t.hereIndex),RR_NOW,2);
 const tomorrow=RR_NOW+rel>=1440;
 // Tomorrow's running is not known yet: show it as planned.
 return tomorrow?{...t,boardRel:rel,tomorrow,status:'On time'}:{...t,boardRel:rel,tomorrow};
}
function rrBoardStatus(t,isArrival){
 const s=stopStatus(t,t.hereIndex);
 if(statusTone(s)==='cancelled'||t.tomorrow)return s;
 const rel=t.boardRel;
 if(!isArrival&&rel>=-2&&rel<=3)return 'Boarding';
 if(isArrival&&rel>=-2&&rel<=0)return 'Arriving';
 return s;
}
function upcoming(station){return TRAINS.map(t=>{const index=t.route.findIndex(s=>s[0]===station);if(index<0||index===t.route.length-1)return null;return{...t,hereTime:t.route[index][1],hereIndex:index}}).filter(Boolean).map(rrWithBoardTime).sort((a,b)=>a.boardRel-b.boardRel||a.id.localeCompare(b.id))}
function arriving(station){return TRAINS.map(t=>{const index=t.route.findLastIndex(s=>s[0]===station);if(index<=0)return null;   /* the last time it is there: a ring lap arrives back at its first station */return{...t,hereTime:t.route[index][1],hereIndex:index}}).filter(Boolean).map(rrWithBoardTime).sort((a,b)=>a.boardRel-b.boardRel||a.id.localeCompare(b.id))}
let departures=[];
let serviceFilter='all',rrStationNetwork=null,rrBoardShown=15,rrBoardKey='';
const RR_BOARD_PAGE=15;
function rrNetworkAt(station){const c=new Map();for(const t of TRAINS)if(t.type==='Regio'&&t.network&&t.route.some(r=>r[0]===station))c.set(t.network,(c.get(t.network)||0)+1);let best=null,n=0;for(const [k,v] of c)if(v>n){best=k;n=v}return best}
new MutationObserver(()=>{if(typeof drawMap==='function'){drawMap();if(typeof drawRoute==='function'&&(selectedTrain||selectedJourney||selectedPath.length))drawRoute()}}).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
const RR_MAINLINE_TYPES=new Set(['Max','VIA','InterCity','Nightline']);
function rrMatchesFilter(t){
 if(serviceFilter==='all')return true;
 if(serviceFilter==='mainline')return RR_MAINLINE_TYPES.has(t.type);
 if(serviceFilter==='regio')return t.type==='Regio'&&(!rrStationNetwork||t.network===rrStationNetwork);
 return t.type==='Local';
}
document.querySelectorAll('.service-chip').forEach(b=>b.addEventListener('click',()=>{
 serviceFilter=b.dataset.filter;app.dataset.sysFocus=serviceFilter;
 document.querySelectorAll('.service-chip').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-checked',String(on))});
 drawBoard();drawMap();
}));
let rrBoardNewList=false;
function drawBoard(){
 if(viewMode==='journeys'){renderJourneyResults();return}
 const isArrival=viewMode==='arrivals';
 app.classList.toggle('no-station',!currentStation);
 $('stationBoardTitle').textContent=isArrival?'Arrivals':'Departures';
 if(!currentStation){
  // Home: no station is assumed. The passenger picks one, or starts from a major station.
  $('stationHeading').textContent='Choose a station';
  board.innerHTML=`<div class="rr-home"><div class="rr-home-title">Major stations</div>${[...LABELS].sort((a,b)=>a.localeCompare(b)).map(n=>`<button type="button" class="rr-home-station" data-station="${n}"><span>${n}</span><span class="jt-chevron" aria-hidden="true"></span></button>`).join('')}</div>`;
  board.querySelectorAll('.rr-home-station').forEach(b=>b.addEventListener('click',()=>setCurrentStation(b.dataset.station)));
  return;
 }
 rrStationNetwork=rrNetworkAt(currentStation);
 departures=(isArrival?arriving(currentStation):upcoming(currentStation)).filter(rrMatchesFilter);
 board.replaceChildren();
 $('stationHeading').textContent=currentStation;
 $('stationBoardTitle').textContent=isArrival?'Arrivals':'Departures';
 $('boardRouteHeader').textContent=isArrival?'From / Via':'To / Via';
 if(!departures.length){board.innerHTML=serviceFilter==='local'?'<div class="empty">No Local services yet.</div>':`<div class="empty">No ${isArrival?'arrivals':'departures'}.</div>`;return}
 // Like journeys: a page of trains, then "Show more trains" (no endless scroll).
 const boardKey=currentStation+'|'+viewMode+'|'+serviceFilter;
 if(boardKey!==rrBoardKey){rrBoardKey=boardKey;rrBoardShown=RR_BOARD_PAGE;rrBoardNewList=true}   // a different list (station, departures / arrivals, filter) starts at the top
 const selIndex=selectedTrain?departures.findIndex(t=>t.id===selectedTrain.id):-1;
 if(selIndex>=rrBoardShown)rrBoardShown=Math.ceil((selIndex+1)/RR_BOARD_PAGE)*RR_BOARD_PAGE;   // keep the chosen train visible
 let dividerShown=false;
 // via (user 2026-11-20): always for ring trains; for others only where the direction is not clear - another train on this
 // board to the same place goes a different way
 const viaOf=new Map(),ways=new Map();
 for(const t of departures.slice(0,rrBoardShown)){const v=rrVia(t,isArrival);viaOf.set(t.id,v);const k=rrDestText(t,isArrival);if(!ways.has(k))ways.set(k,new Set());ways.get(k).add(v[0]||'')}
 for(const t of departures.slice(0,rrBoardShown)){
  if(rrLocalDayOff(t.boardRel)>0&&!dividerShown){dividerShown=true;const d=document.createElement('div');d.className='rr-day-divider';d.textContent=rrDayLabel(1);board.append(d)}
  const row=document.createElement('button');
  row.type='button';
  row.className='trainrow'+(selectedTrain?.id===t.id?' selected':'');
  row.style.setProperty('--service-color',rrTrainCss(t));
  row.style.setProperty('--rr-white-text-fill',rrTrainFill(t));if(rrInk(t))row.style.setProperty('--on-accent','#24282C');
  row.innerHTML=`<span class="row-time">${stopTimeMarkup(t,t.hereIndex)}</span><span class="service${rrOutline(t)?' rr-ic-outline':''}${rrTrainLabel(t).length===1?' service-square':''}">${rrTrainLabel(t)}</span><span><span class="dest">${rrRingIcon(t)}<span>${rrDestText(t,isArrival)}</span></span>${(()=>{const v=viaOf.get(t.id),full=t.ring||ways.get(rrDestText(t,isArrival)).size>1,sh=full?v:v.filter(rrIsAirport);return sh.length||t.fast?`<span class="row-via">${rrFastTag(t)}${sh.length?`<span>via ${sh.map(rrStnText).join(' · ')}</span>`:''}</span>`:''})()}<span class="rowstatus">${statusTag(rrBoardStatus(t,isArrival))}${rrCrowdMarkup(t,t.hereIndex)}</span></span><span class="platform">${rrBoardPlatform(t,currentStation)}</span>`;
  row.addEventListener('click',()=>selectedTrain?.id===t.id?clear():chooseTrain(t));   // a second click deselects: map back to default
  board.append(row);
 }
 if(rrBoardShown<departures.length){
  const more=document.createElement('button');more.type='button';more.className='journey-more';more.textContent='Show more trains';
  more.addEventListener('click',()=>{const y=board.scrollTop;rrBoardShown+=RR_BOARD_PAGE;drawBoard();board.scrollTop=y});
  board.append(more);
 }
 rrFitStatus(board);
 if(rrBoardNewList){rrBoardNewList=false;board.scrollTop=0}
}
// A status that does not fit on its line shortens: "Expected +24 min" -> "Expt +24 min" (display only; the data keeps "Expected")
function rrFitStatus(root){root.querySelectorAll('.rowstatus').forEach(rs=>{const tag=rs.querySelector('.status-tag');if(!tag)return;
 const long=tag.dataset.long||tag.textContent;if(!/^Expected /.test(long))return;tag.dataset.long=long;if(tag.textContent!==long)tag.textContent=long;
 const wraps=()=>{const b=tag.getBoundingClientRect().bottom;return tag.getClientRects().length>1||[...rs.children].some(c=>c!==tag&&c.getBoundingClientRect().top>=b-2)};
 // still no room (user 2026-11-21: "Expt +32 min" pushed the crowding figures onto a new line): the delay alone, then without "min"; the tag's colour still says expected
 if(wraps())tag.textContent=long.replace(/^Expected /,'Expt ');if(wraps()&&/^Expected \+/.test(long))tag.textContent=long.replace(/^Expected /,'');if(wraps())tag.textContent=tag.textContent.replace(/ min$/,'');tag.title=tag.textContent!==long?long:''})}
new ResizeObserver(()=>rrFitStatus(board)).observe(board);
function setCurrentStation(name){rrLocalSystem=null;rrFocusSystem=null;
 viewMode=viewMode==='arrivals'?'arrivals':'departures';
 updateBoardTabs();
 const moved=!!name&&name!==currentStation;
 selectedJourney=null;selectedLegPaths=[];selectedRouteLine=null;currentStation=name;
 rrSelectValue(stationSelect,name);pickerViews.get('stationSelect')?.sync();
 selectedTrain=null;selectedPath=[];selectedNames=name?[name]:[];manualTrace=false;
 routeWorld.replaceChildren();drawBoard();app.classList.remove('detail-open');
 requestAnimationFrame(resize);
 detail.innerHTML='<div class="empty">Select a train to view details.</div>';
 $('focusRoute').hidden=true;
 if(moved)rrFocusStation(name);
 drawMap();
}

// SVG artwork supplied by the RR design team.
